import { useState } from "react";
import "./App.css";

export default function AccountSettings({ userEmail, onBack, onEmailChange }) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  
  const [showPasswordFields, setShowPasswordFields] = useState(false);
  const [showEmailFields, setShowEmailFields] = useState(false);
  
  const [currentPassword, setCurrentPassword] = useState("");
  const [newEmail, setNewEmail] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validation
    if (!currentPassword) {
      setError("❌ Introdu parola curentă pentru a verifica identitatea");
      return;
    }

    if (!showEmailFields && !showPasswordFields) {
      setError("❌ Selectează ce dorești să modifici (Email sau Parolă)");
      return;
    }

    if (showPasswordFields) {
      if (!newPassword) {
        setError("❌ Introdu noua parolă");
        return;
      }
      if (newPassword.length < 6) {
        setError("❌ Parola nouă trebuie să aibă cel puțin 6 caractere");
        return;
      }
      if (newPassword !== confirmPassword) {
        setError("❌ Parolele nu se potrivesc");
        return;
      }
    }

    if (showEmailFields) {
      if (!newEmail) {
        setError("❌ Introdu noul email");
        return;
      }
      if (!newEmail.includes("@")) {
        setError("❌ Email-ul nu este valid");
        return;
      }
      if (newEmail === userEmail) {
        setError("❌ Noul email este identic cu cel actual");
        return;
      }
    }

    setSaving(true);
    setError("");
    setSuccess("");

    try {
      const apiData = {
        current_password: currentPassword,
        new_email: showEmailFields ? newEmail : null,
        new_password: showPasswordFields ? newPassword : null
      };

      const res = await fetch(`http://localhost:8001/account_settings/${userEmail}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(apiData)
      });

      const data = await res.json();

      if (res.ok && data.status === "success") {
        setSuccess(`✅ ${data.message}`);
        
        // Reset form
        setCurrentPassword("");
        setNewEmail("");
        setNewPassword("");
        setConfirmPassword("");
        setShowEmailFields(false);
        setShowPasswordFields(false);
        
        // If email was changed, notify parent component
        if (data.new_email && data.new_email !== userEmail) {
          setTimeout(() => {
            if (onEmailChange) {
              onEmailChange(data.new_email);
            }
          }, 2000);
        }
      } else {
        setError(`❌ ${data.detail || "Eroare la actualizarea setărilor"}`);
      }
    } catch (err) {
      setError("❌ Eroare la conectarea cu serverul");
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh", padding: "2rem" }}>
      <div style={{ maxWidth: "600px", margin: "0 auto" }}>
        <button
          className="btn btn-secondary"
          onClick={onBack}
          style={{ marginBottom: "2rem" }}
        >
          ← Înapoi
        </button>

        <div className="card" style={{ padding: "2rem" }}>
          <h2 style={{ 
            fontSize: "2rem", 
            fontWeight: "700", 
            color: "#ff6b35", 
            marginBottom: "0.5rem",
            textAlign: "center"
          }}>
            ⚙️ Setările Contului
          </h2>
          <p style={{ 
            color: "#666", 
            fontSize: "0.95rem", 
            textAlign: "center",
            marginBottom: "2rem"
          }}>
            Modifică email-ul sau parola contului tău
          </p>

          {error && (
            <div style={{
              padding: "1rem",
              background: "rgba(244, 67, 54, 0.1)",
              border: "1px solid rgba(244, 67, 54, 0.3)",
              borderRadius: "8px",
              color: "#d32f2f",
              marginBottom: "1rem"
            }}>
              {error}
            </div>
          )}

          {success && (
            <div style={{
              padding: "1rem",
              background: "rgba(76, 175, 80, 0.1)",
              border: "1px solid rgba(76, 175, 80, 0.3)",
              borderRadius: "8px",
              color: "#388e3c",
              marginBottom: "1rem"
            }}>
              {success}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            {/* Current Email Display */}
            <div style={{
              padding: "1rem",
              background: "rgba(33, 150, 243, 0.05)",
              borderRadius: "8px",
              marginBottom: "1.5rem",
              border: "1px solid rgba(33, 150, 243, 0.2)"
            }}>
              <p style={{ margin: 0, color: "#666", fontSize: "0.9rem" }}>
                📧 <strong>Email curent:</strong> {userEmail}
              </p>
            </div>

            {/* What to Change Selection */}
            <div style={{ marginBottom: "1.5rem" }}>
              <label style={{ 
                display: "block", 
                fontWeight: "600", 
                marginBottom: "0.8rem",
                color: "#333"
              }}>
                Ce dorești să modifici?
              </label>
              
              <div style={{ display: "flex", gap: "1rem" }}>
                <button
                  type="button"
                  className={`btn ${showEmailFields ? 'btn-primary' : 'btn-outline'}`}
                  onClick={() => {
                    setShowEmailFields(!showEmailFields);
                    setError("");
                    setSuccess("");
                  }}
                  style={{ flex: 1 }}
                >
                  📧 Email
                </button>
                
                <button
                  type="button"
                  className={`btn ${showPasswordFields ? 'btn-primary' : 'btn-outline'}`}
                  onClick={() => {
                    setShowPasswordFields(!showPasswordFields);
                    setError("");
                    setSuccess("");
                  }}
                  style={{ flex: 1 }}
                >
                  🔐 Parolă
                </button>
              </div>
            </div>

            {/* New Email Field */}
            {showEmailFields && (
              <div style={{ marginBottom: "1rem" }}>
                <label style={{ 
                  display: "block", 
                  fontWeight: "600", 
                  marginBottom: "0.5rem",
                  color: "#333"
                }}>
                  📧 Email Nou
                </label>
                <input
                  type="email"
                  value={newEmail}
                  onChange={(e) => setNewEmail(e.target.value)}
                  placeholder="exemplu@email.com"
                  style={{
                    width: "100%",
                    padding: "0.75rem",
                    border: "2px solid #e0e0e0",
                    borderRadius: "8px",
                    fontSize: "1rem",
                    outline: "none",
                    transition: "border-color 0.3s"
                  }}
                  onFocus={(e) => e.target.style.borderColor = "#ff6b35"}
                  onBlur={(e) => e.target.style.borderColor = "#e0e0e0"}
                />
              </div>
            )}

            {/* New Password Fields */}
            {showPasswordFields && (
              <>
                <div style={{ marginBottom: "1rem" }}>
                  <label style={{ 
                    display: "block", 
                    fontWeight: "600", 
                    marginBottom: "0.5rem",
                    color: "#333"
                  }}>
                    🔐 Parolă Nouă
                  </label>
                  <input
                    type="password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="Minim 6 caractere"
                    style={{
                      width: "100%",
                      padding: "0.75rem",
                      border: "2px solid #e0e0e0",
                      borderRadius: "8px",
                      fontSize: "1rem",
                      outline: "none",
                      transition: "border-color 0.3s"
                    }}
                    onFocus={(e) => e.target.style.borderColor = "#ff6b35"}
                    onBlur={(e) => e.target.style.borderColor = "#e0e0e0"}
                  />
                </div>

                <div style={{ marginBottom: "1rem" }}>
                  <label style={{ 
                    display: "block", 
                    fontWeight: "600", 
                    marginBottom: "0.5rem",
                    color: "#333"
                  }}>
                    🔐 Confirmă Parola Nouă
                  </label>
                  <input
                    type="password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    placeholder="Re-introdu parola"
                    style={{
                      width: "100%",
                      padding: "0.75rem",
                      border: "2px solid #e0e0e0",
                      borderRadius: "8px",
                      fontSize: "1rem",
                      outline: "none",
                      transition: "border-color 0.3s"
                    }}
                    onFocus={(e) => e.target.style.borderColor = "#ff6b35"}
                    onBlur={(e) => e.target.style.borderColor = "#e0e0e0"}
                  />
                </div>
              </>
            )}

            {/* Divider */}
            {(showEmailFields || showPasswordFields) && (
              <div style={{
                height: "1px",
                background: "#e0e0e0",
                margin: "1.5rem 0"
              }}></div>
            )}

            {/* Current Password Verification */}
            <div style={{ marginBottom: "1.5rem" }}>
              <label style={{ 
                display: "block", 
                fontWeight: "600", 
                marginBottom: "0.5rem",
                color: "#333"
              }}>
                🔒 Parola Curentă (pentru verificare)
              </label>
              <input
                type="password"
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                placeholder="Introdu parola curentă"
                required
                style={{
                  width: "100%",
                  padding: "0.75rem",
                  border: "2px solid #e0e0e0",
                  borderRadius: "8px",
                  fontSize: "1rem",
                  outline: "none",
                  transition: "border-color 0.3s"
                }}
                onFocus={(e) => e.target.style.borderColor = "#ff6b35"}
                onBlur={(e) => e.target.style.borderColor = "#e0e0e0"}
              />
            </div>

            <button
              type="submit"
              className="btn btn-primary"
              disabled={saving || (!showEmailFields && !showPasswordFields)}
              style={{
                width: "100%",
                padding: "1rem",
                fontSize: "1.1rem",
                fontWeight: "600",
                opacity: (!showEmailFields && !showPasswordFields) ? 0.5 : 1
              }}
            >
              {saving ? "Se salvează..." : "💾 Salvează modificările"}
            </button>
          </form>
        </div>

        <div style={{
          marginTop: "1.5rem",
          padding: "1rem",
          background: "rgba(255, 193, 7, 0.1)",
          borderRadius: "8px",
          border: "1px solid rgba(255, 193, 7, 0.3)"
        }}>
          <p style={{ fontSize: "0.9rem", color: "#666", margin: 0 }}>
            ⚠️ <strong>Atenție:</strong> Pentru securitatea contului tău, trebuie să introduci parola curentă pentru orice modificare. Dacă modifici email-ul, vei fi delogat automat.
          </p>
        </div>
      </div>
    </div>
  );
}
